{"name": "run_python", "parameters": {"code": "import json
from csv import reader
with open('CATALOG_CSV') as f:
    catalog = {row[0]: row for row in reader(f)}
with open('VALUES_CSV") as f:
    values = {row[0]: {'timestamp': row[1], 'value': row[2]} for row in reader(f)}
series_ids = [row[0] for row in catalog.values() if row[1] == "Electricity"]
b = [row for row in values.values() if row['timestamp'] in ['2018-01-10', '2018-10-13'] and row[0] in series_ids]
b.sort(key=lambda x: x['timestamp'])
print(json.dumps(1000 * (b[0][1] - b[1][1])))"}}
